// https://stackoverflow.com/a/59599339
const inp = (id, val) => {
    const el = document.querySelector(`[id="${id}"]`);
    el.value = val;
    let event = new Event('input', { bubbles: true });
    // hack React15
    event.simulated = true;
    // hack React16 内部定义了descriptor拦截value，此处重置状态
    let tracker = el._valueTracker;
    if (tracker) tracker.setValue('');
    el.dispatchEvent(event);
};

const wait = ms => new Promise(r => setTimeout(r, ms));

window.addEventListener('load', async () => {
    while (true) {
        if (document.querySelector('h2[data-client-id="heading_Organization Information"]')) break;
        await wait(10);
    }

    while (true) {
        const el = document.querySelector('[data-client-id~="checkbox_Move"]:not(:checked)');
        if (!el) break;
        el.click();
        await wait(100);
    }

    const schoolCode = prompt('enter school code').trim().toUpperCase();
    let zipCode = zipCodes[schoolCode].split(' ').pop();
    if (!/^\d{5}$/.test(zipCode)) zipCode = '';
    const school = schoolData.find(s => s.code === schoolCode);

    // Organization Information
    inp('text_box_Name of Applicant (Organization/Vendor)', 'Tri-Star Plumbing & Heating');
    inp('text_box_Tax ID', '263941871');
    inp('text_box_Name of Authorized Representative', 'M. Mando');
    inp('text_box_Title of Authorized Representative', 'VP');
    inp('text_box_Email of Authorized Representative', 'jason@tristarplumbing.net');
    inp('text_box_Phone', '7188554445');

    // Permit Information
    if (school) {
        inp('text_box_School Name', school.name);
        inp('text_box_School Borough', school.code);
        inp('select_input_School District', `District ${school.district}`);
        document.querySelector('.react-select__option--is-focused').click();
        await wait(10);
        inp('text_box_School Mailing Address', school.address);
        inp('text_box_City', school.borough);

        const cust = school.contacts[0];
        if (cust) {
            inp('text_box_School Phone #', cust.office.replace(/-/g, '').slice(0, 10));
            inp('text_box_Name Of Custodial Engineer', cust.name);
            inp('text_box_Custodial Engineer Email', cust.email);
            // inp('text_box_Principal/Designated Email', cust.email);
        }
    }

    inp('select_input_State', 'New York');
    document.querySelector('.react-select__option--is-focused').click();
    await wait(10);
    if (zipCode) {
        inp('text_box_School Zip Code', zipCode);
    }

    // Special Requests
    document.querySelector('[data-client-id="radio_Do you have a special request?"][data-client-value="No"]').click();

    // Permit Details

    // Times of Use
    document.querySelector('[data-client-id="radio_Alternative School Safety?"][data-client-value="No"]').click();
    document.querySelector('[data-client-id="checkbox_Please review the entire form carefully to ensure that all information entered is correct. Any inaccuracies will necessitate resubmitting a new permit request."]').click();
    document.querySelector('[data-client-id="checkbox_<-"]').click();
}, false);